// ---------------------------------------------------------------------------
// The trait stack
//
// One associated `Out` flows through all three traits, so an interpreter, a
// bytecode emitter, and a typechecker are three impls over one grammar.
// ---------------------------------------------------------------------------

pub trait Semantics {
    /// What evaluating a node produces.
    type Out;
}

/// A host whose `Out` is a **value it can ask questions about**.
///
/// An interpreter implements this: `Out` is a value, and truthiness is
/// a question it can answer. A compiler does not: its `Out` is a
/// placeholder for something the *target machine* will compute later,
/// so there is nothing to inspect at build time.
///
/// It is separate from [`Semantics`] for exactly that reason. Requiring
/// it of every host would force a bytecode emitter to write a `truthy`
/// it can never answer and must never be asked.
pub trait Values: Semantics {
    /// The one host-specific part of short-circuiting. Give us this
    /// and `nh_handlers!` writes `&&`, `||` and `??` for you.
    fn truthy(&self, value: &Self::Out) -> bool;

    /// Used by the `??` body. Languages without a null need not
    /// override it.
    fn is_null(&self, value: &Self::Out) -> bool {
        let _ = value;
        false
    }
}

// ---------------------------------------------------------------------------
// Grouped-role discriminants
//
// Several operators binding one role produce a single trait method taking
// this enum, instead of six near-identical methods (DESIGN.md §6.3).
// ---------------------------------------------------------------------------

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum CompareOp {
    /// `=`
    Eq,
    /// `<>`
    LtGt,
    /// `<`
    Lt,
    /// `<=`
    LtEq,
    /// `>`
    Gt,
    /// `>=`
    GtEq,
}

impl CompareOp {
    /// The operator as written in the source language.
    pub fn spelling(self) -> &'static str {
        match self {
            CompareOp::Eq => "=",
            CompareOp::LtGt => "<>",
            CompareOp::Lt => "<",
            CompareOp::LtEq => "<=",
            CompareOp::Gt => ">",
            CompareOp::GtEq => ">=",
        }
    }
}

/// Operators that are **lazy in their right operand**.
///
/// Separate from [`Operators`] because their meaning is the one thing
/// that genuinely differs between an interpreter and a compiler:
/// short-circuiting is a *decision* to one and *control flow* to the
/// other.
///
/// **You almost certainly do not implement this.** `nh_handlers!` writes
/// the interpreter's version from your [`Values`] impl. Write it yourself
/// only if you are emitting code rather than producing values, and then
/// say so:
///
/// ```ignore
/// nh_handlers!(Interp, without short_circuit);
/// ```
pub trait ShortCircuit: Semantics {

    /// `ORELSE` — **lazy in its right operand**.
    ///
    /// `rhs` is unevaluated. Running it is what evaluates it; not
    /// running it is what makes this short-circuit.
    ///
    /// An interpreter gets this written for it by `nh_handlers!`. A
    /// compiler writes it, emitting a jump — short-circuiting is
    /// control flow to it, not a decision.
    fn or_else(
        &mut self,
        lhs: Self::Out,
        rhs: Shared<Expr>,
        cx: &mut Ctx,
    ) -> Result<Self::Out>
    where
        Self: Handlers + Sized;

    /// `ANDALSO` — **lazy in its right operand**.
    ///
    /// `rhs` is unevaluated. Running it is what evaluates it; not
    /// running it is what makes this short-circuit.
    ///
    /// An interpreter gets this written for it by `nh_handlers!`. A
    /// compiler writes it, emitting a jump — short-circuiting is
    /// control flow to it, not a decision.
    fn and_then(
        &mut self,
        lhs: Self::Out,
        rhs: Shared<Expr>,
        cx: &mut Ctx,
    ) -> Result<Self::Out>
    where
        Self: Handlers + Sized;
}

/// Operator semantics.
